/bin/zsh -c "python3 -c 'import numpy as np, math; from scipy.special import zeta; N=2000000; sieve=np.ones(N+1,dtype=bool); sieve[:2]=False
for n in range(2,math.isqrt(N)+1):
 if sieve[n]: sieve[n*n::n]=False
P=np.flatnonzero(sieve); p=P.astype(float); den=p*p+p-2; b1=(np.sqrt(p)-p)/den; b2=(1-np.sqrt(p))/den; base=(2/3)*zeta(1.5,1)/math.pi*np.prod(1-3/p**2+2/p**3); print(\"unrestricted baseline\",base)
for name in [\"k"'^2+1","k''^3+2","2k+1"]:
 r1=np.zeros(len(P));r2=np.zeros(len(P))
 for i,pp in enumerate(P):
  q=int(pp)
  if name=="k''^2+1": a=(1 if q==2 else 2 if q%4==1 else 0);b=(0 if q==2 else a)
  elif name=="2k+1": a=b=int(q!=2)
  else:
   if q==2:a,b=1,0
   elif q==3:a,b=1,0
   elif q%3==2:a=b=1
   else:a=b=(3 if pow(q-2,(q-1)//3,q)==1 else 0)
  r1[i]=a;r2[i]=b
 avg=np.prod(1+b1*r1/p+b2*r2/p**2);print(name,"mean",avg,"constant",base*avg)
'"'"

