/bin/zsh -c "python3 -c 'import numpy as np, math,json; from scipy.special import zeta; from sympy import primerange, factorint; x=1000000; P=list(primerange(2,10000)); c=6/math.pi**2; C=c*c/np.prod([1+1/(p*p*(p*p-2)) for p in P]); S=np.full(x+1,C)
for p in P:
 if p*p<=x:S[p*p::p*p]*=(p*p-1)/(p*p-2)
K=zeta(1.5,1)/math.pi*np.prod([1-3/p**2+2/p**3 for p in P]); j=json.load(open(\"results.json\"))
for name,v in j[\"polynomials\"].items():
 print(name)
 for row in v[\"rows\"]:
  if row[\"x\"]"'!=x or row["ratio_target"] not in [.01,.1,1.0]:continue
  off=Ds=W=As=0.
  for k in range(1,row["y"]+1):
   q,w=(k*k+1,2*k) if name=="k''^2+1" else (k*k*k+2,3*k*k) if name=="k''^3+2" else (2*k+1,2)
   D=c*c/q;A=1.
   for pp,e in factorint(q).items():
    p=int(pp); den=p*p+p-2
    D*=((1+1/(p*(p*p-2))) if e==1 else (1+1/(p*p-2)))/(1+1/(p*p*(p*p-2)))
    A*=(p*p-2+math.sqrt(p))/den if e==1 else (p*p-1)/den
   lag=np.arange(q,x+1,q);off+=w*np.dot(x-lag,S[lag]); Ds+=w*D;W+=w;As+=w*math.sqrt(q)*A
  scale=math.sqrt(x)*row["fy"]**1.5; model=(c*x*W+2*off-x*x*Ds)/scale; leading=K*math.sqrt(x)*As/scale
  print(row["ratio_actual"],"actual",round(row["normalised"],8),"pair_model",round(model,8),"local_leading",round(leading,8))
'"'"

